def init_public_agents():
    os.makedirs(DATA_DIR, exist_ok=True)
    registry = {
        "version": "V1.0",
        "total_agents": len(PUBLIC_AGENTS),
        "categories": ["政务服务", "通用AI", "效率工具", "生活服务", "创意设计"],
        "agents": PUBLIC_AGENTS,
        "created_at": datetime.datetime.now().isoformat(),
        "did": "DID-BR-000002",
        "trace_mark": "Ω₀⊂⊙∞⊂Ω"
    }
    with open(PUBLIC_AGENTS_FILE, 'w', encoding='utf-8') as f:
        json.dump(registry, f, ensure_ascii=False, indent=2)
    return len(PUBLIC_AGENTS)

def list_public_agents(category=None):
    if category:
        return [a for a in PUBLIC_AGENTS.values() if a.get('category') == category]
    return list(PUBLIC_AGENTS.values())

def get_public_agent(agent_id):
    return PUBLIC_AGENTS.get(agent_id)

def get_categories():
    return list(set(a['category'] for a in PUBLIC_AGENTS.values()))

if __name__ == '__main__':
    n = init_public_agents()
    print(f"面向普通用户的智能体矩阵初始化完成，共{n}个智能体")
    cats = {}
    for a in PUBLIC_AGENTS.values():
        cats.setdefault(a['category'], []).append(a['name'])
    for cat, names in cats.items():
        print(f"  【{cat}】({len(names)}个): {', '.join(names)}")
